spec.expr:
count(
  sum by (chat_ref) (
    count_over_time(
      {app="anon3anon", container="anon3anon"}
        | json
        | chat_ref!=""
        [$__range]
    )
  )
)

sum by (message_kind) (
  count_over_time(
    {app="anon3anon", container="anon3anon"}
      | json
      | message_kind!=""
      [$__range]
  )
)

sum(
  count_over_time(
    {app="anon3anon", container="anon3anon"}
    | json
    | message_kind!="command"
    | is_reply="true"
    [$__range]
  )
)

sum by (is_reply) (
  count_over_time(
    {app="anon3anon", container="anon3anon"}
    | json
    | message_kind!="command"
    | is_reply=~"true|false"
    [$__interval]
  )
)

sum by (is_reply) (
  count_over_time(
    {app="anon3anon", container="anon3anon"}
      | json
      | message_kind!="command"
      | is_reply=~"true|false"
      [$__range]
  )
)
